# DK RSV.  Rønne Nord - Sandvig
#
let rs = path("d3.dk.rsv");

with detail = 3, railway = :third :narrow:g1000 :pax :removed {
    # point.dk.Rønne-Nord  dk.RNX

    with link = "line.dk.RSV" {
        track(
                rs[:ron.ya - 0.1dl, :ron.ya] << 1ls << 1lt
            ..  rs[:ron.xa + 1lt, :ron.xa + 1.01km]
        );
        line_label(:left:e, rs[:ron.xa + 1km] << 0.5lt, (0dt, -0.1dt), "RSV");
        track(rs[:ron.xa + 0.99km, :bly - 0.49sw]);
    }

    with link = "point.dk.Blykobbe", railway = :station {
        track(rs[:bly - 0.5sw, :bly + 0.5sw]);
        marker(:left :de.hp, rs[:bly] << 0.5lt);
        slabel(:left, rs[:bly] << 0.5lt << 1sh + (-1.4dt, 0.6dt),
            "Blykobbe"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:bly + 0.49sw, :nyk - 0.49sw]);
    }

    with link = "point.dk.Nyker", railway = :station {
        track(rs[:nyk - 0.5sw, :nyk + 0.5sw]);
        marker(:right :de.bf, rs[:nyk] >> 0.5lt);
        slabel(:right, rs[:nyk] >> 0.5lt >> 1sh + (1.4dt, 1.2dt),
            "Nyker"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:nyk + 0.49sw, :mab - 0.49sw]);
    }

    with link = "point.dk.Mæby", railway = :station {
        track(rs[:mab - 0.5sw, :mab + 0.5sw]);
        marker(:right :de.hp, rs[:mab] >> 0.5lt);
        slabel(:right, rs[:mab] >> 0.5lt >> 1sh + (1.4dt, 1.2dt),
            "Mæby"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:mab + 0.49sw, :kle - 0.49sw]);
    }

    with link = "point.dk.Klemensker", railway = :station {
        track(rs[:kle - 0.5sw, :kle + 0.5sw]);
        marker(:right :de.bf, rs[:kle] >> 0.5lt);
        slabel(:right, rs[:kle] >> 0.5lt >> 1sh + (1.4dt, 1.2dt),
            "Klemensker"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:kle + 0.49sw, :spl - 0.49sw]);
    }

    with link = "point.dk.Splidsgård", railway = :station {
        track(rs[:spl - 0.5sw, :spl + 0.5sw]);
        marker(:left :de.hp, rs[:spl] << 0.5lt);
        slabel(:left, rs[:spl] << 0.5lt << 1sh + (-1.5dt, 0.5dt),
            "Splidsgård"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:spl + 0.49sw, :spl + 1.61km]);
        line_label(:right:nw, rs[:spl + 1.6km] >> 0.5lt, "RSV");
        track(rs[:spl + 1.59km, :spe + 0.1dl]);
    }

    with link = "point.dk.Spellingmose", railway = :station {
        marker(:left :de.anst, rs[:spe] << 0.5lt);
        slabel(:left, rs[:spe] << 0.5lt << 1sh + (1.5dt, -1dt),
            span(:xsmall, "Spellingmose")
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:spe - 0.1dl, :roe - 0.49sw]);
    }

    with link = "point.dk.Rø", railway = :station {
        track(rs[:roe - 0.5sw, :roe + 0.5sw]);
        marker(:right :de.bf, rs[:roe] >> 0.5lt);
        slabel(:right, rs[:roe] >> 0.5lt >> 1sh + (1.3dt, 1.2dt),
            "Rø*"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:roe - 0.49sw, :hel - 0.49sw]);
    }

    with link = "point.dk.Helligdommen", railway = :station {
        track(rs[:hel - 0.5sw, :hel + 0.5sw]);
        marker(:right :de.hp, rs[:hel] >> 0.5lt);
        slabel(:right, rs[:hel] >> 0.5lt >> 1sh + (1.2dt, 1dt),
            "Helligdommen"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:hel - 0.49sw, :hum - 0.49sw]);
    }

    with link = "point.dk.Humledal", railway = :station {
        track(rs[:hum - 0.5sw, :hum + 0.5sw]);
        marker(:right :de.bf, rs[:hum] >> 0.5lt);
        slabel(:right, rs[:hum] >> 0.5lt >> 1sh + (1.4dt, 0.5dt),
            "Humledal"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:hum - 0.49sw, :tej - 0.49sw]);
    }

    with link = "point.dk.Tejn", railway = :station {
        track(rs[:tej - 0.5sw, :tej + 0.5sw]);
        marker(:left :de.bf, rs[:tej] << 0.5lt);
        slabel(:bottom, rs[:tej] << 0.5lt << 1sh + (-0.8dt, 0.4dt),
            "Tejn"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:tej - 0.49sw, :sak - 0.49sw]);
    }

    with link = "point.dk.Sandkås", railway = :station {
        track(rs[:sak - 0.5sw, :sak + 0.5sw]);
        marker(:right :de.hp, rs[:sak] >> 0.5lt);
        slabel(:right, rs[:sak] >> 0.5lt >> 1sh + (1.2dt, 1dt),
            "Sandkås"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:sak - 0.49sw, :all - 0.49sw]);
    }

    with link = "point.dk.Allinge", railway = :station {
        track(rs[:all - 0.5sw, :all + 0.5sw]);
        marker(:right :de.bf, rs[:all] >> 0.5lt);
        slabel(:right, rs[:all] >> 0.5lt >> 1sh + (1.3dt, 0.9dt),
            "Allinge"
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:all - 0.49sw, :all + 1.21km]);
        line_label(:left:e, rs[:all + 1.2km] << 0.5lt, (0dt, 0.2dt), "RSV");
        track(rs[:all - 1.19km, :kor + 0.1dl]);
    }

    with link = "point.dk.Korsbjerg", railway = :station {
        marker(:right :de.anst, rs[:kor] >> 0.5lt);
        slabel(:right, rs[:kor] >> 0.5lt >> 1sh + (1.3dt, 0.5dt),
            span(:xsmall, "Korsbjerg")
        );
    }

    with link = "line.dk.RSV" {
        track(rs[:kor - 0.1dl, :san - 0.49sw]);
    }

    with link = "point.dk.Sandvig", railway = :station {
        track(rs[:san - 0.5sw, :san + 0.5sw]);
        marker(:right :de.bf, rs[:san] >> 0.5lt);
        slabel(:top, rs[:san] >> 0.5lt >> 1sh >> 0.4dt,
            hbox(:center:base, span(:bold, "Sandvig"), "*")
        );
    }
}

